'use strict';
// data/voice/amy.js — amy's baked clips (loaded after data/voice-clips.js). Merge from the Voice Baker; do not hand-edit.
VOICE_CLIPS.clips.amy={"greet":[{"text":"Tom, I ran eight miles before you woke up.","mp3":"","model":"eleven_v4"},{"text":"Race you to the fountain. No? Then I win.","mp3":"","model":"eleven_v4"},{"text":"Grace! Rose! Did you stretch?","mp3":"","model":"eleven_v4"}],"basic":[{"text":"Coming through! Hydrate later!","mp3":"","model":"eleven_v4"},{"text":"Heads up! Mom has a record to set!","mp3":"","model":"eleven_v4"}],"hurt":[{"text":"Ow! Okay. I'm okay.","mp3":"","model":"eleven_v4"},{"text":"Hey! That's a time penalty!","mp3":"","model":"eleven_v4"},{"text":"That was a lot. I'm going to count to three.","mp3":"","model":"eleven_v4"}],"win":[{"text":"That's how this family does it!","mp3":"","model":"eleven_v4"},{"text":"Faster than Tom. As usual.","mp3":"","model":"eleven_v4"},{"text":"Everybody did their job. I saw every bit of it.","mp3":"","model":"eleven_v4"}],"praise":[{"text":"Neatest handwriting in the building. And I check.","mp3":"","model":"eleven_v4"},{"text":"Your margins are immaculate. Gold star.","mp3":"","model":"eleven_v4"},{"text":"Here! Gregori, party of four. We're always first in line.","mp3":"","model":"eleven_v4"},{"text":"You waited your turn. That's the hardest thing there is. Gold star.","mp3":"","model":"eleven_v4"},{"text":"Present. I've never missed a connection in my life.","mp3":"","model":"eleven_v4"}],"join":[{"text":"Need a fourth? I'm fast, I'm patient, and I brought snacks.","mp3":"","model":"eleven_v4"}],"quiz":[{"text":"Surprise quiz! Don't panic. You know this. Take your time.","mp3":"","model":"eleven_v4"}],"pep":[{"text":"Look at me. Breathe. You've done this before. Go.","mp3":"","model":"eleven_v4"},{"text":"Eyes up, team! Stretching is over!","mp3":"","model":"eleven_v4"}],"tombo2":[{"text":"Ketchup, pickles, chocolate. It's a Ymamot Creation!","mp3":"","model":"eleven_v4"}],"hills":[{"text":"Hill repeats! Up the hill, down the hill!","mp3":"","model":"eleven_v4"}],"marathon":[{"text":"Twenty-six point two! Straight through the finish line!","mp3":"","model":"eleven_v4"}],"marathon_ult":[{"text":"Twenty-six point two miles complete! Sprint to the finish!","mp3":"","model":"eleven_v4"}],"flashback":[{"text":"Flashback!","mp3":"","model":"eleven_v4"}],"oat_milk_please":[{"text":"No dairy, thank you. Almond milk, please!","mp3":"","model":"eleven_v4"}],"tombo3":[{"text":"He STARTED it! That's MY spot!","mp3":"","model":"eleven_v4"}],"dc1":[{"text":"Five, six, seven, eight! Jazz hands, Tom! JAZZ HANDS!","mp3":"","model":"eleven_v4"}],"burpee":[{"text":"Five burpees. Four. Three. Breathe. You can do hard things.","mp3":"","model":"eleven_v4"}],"finish":[{"text":"I see the finish line. It's you.","mp3":"","model":"eleven_v4"}],"redpen":[{"text":"I circled what you did well. Now the rest.","mp3":"","model":"eleven_v4"}],"pb":[{"text":"New personal best! Write it down, Tom!","mp3":"","model":"eleven_v4"}],"kettlebell_swing":[{"text":"Kettlebell swing! Hips, not back!","mp3":"","model":"eleven_v4"}],"hot_lunch_tray":[{"text":"Hot lunch! Soup first, then recess.","mp3":"","model":"eleven_v4"}],"goldstar_recess":[{"text":"Gold-star recess. Rest counts as good work.","mp3":"","model":"eleven_v4"}],"inside_voices":[{"text":"Inside voices, please. I'll wait.","mp3":"","model":"eleven_v4"}],"hill_repeats":[{"text":"Heart rate 185 and I'm still TALKING.","mp3":"","model":"eleven_v4"}],"false_start":[{"text":"False start. Back behind the line.","mp3":"","model":"eleven_v4"}],"negative_split":[{"text":"Negative split! The second half is FASTER!","mp3":"","model":"eleven_v4"}],"detention_ult":[{"text":"Nobody leaves this room until every single one of you knows how good you are.","mp3":"","model":"eleven_v4"}],"low":[{"text":"Walking it off. Walking it off.","mp3":"","model":"eleven_v4"}],"ko":[{"text":"Time. Out. Somebody hydrate me.","mp3":"","model":"eleven_v4"}],"tombo":[{"text":"I called it! Get your own monster!","mp3":"","model":"eleven_v4"}],"dc2":[{"text":"Streamers higher, Tom! Grace is going to LOVE this!","mp3":"","model":"eleven_v4"}],"dc3":[{"text":"Shortcuts don't COUNT, Tom!","mp3":"","model":"eleven_v4"}],"ff2":[{"text":"My girls. Okay, hands together! Nobody stops the three of us!","mp3":"","model":"eleven_v4"}]};
